import SwiftUI
struct ContentView: View {
 var message: String {
  guard let url = Bundle.main.url(forResource: "message", withExtension: "txt", subdirectory: "Resources/Data"), let text = try? String(contentsOf: url, encoding: .utf8) else { return "Resource missing" }
  return text
 }
 var body: some View { Text(message).padding() }
}
